import { test, expect } from "@playwright/test";
import { randomUUID } from "crypto";

function uniqueEmail(): string {
  return `test-waitlist-${randomUUID()}@example.com`;
}

test.describe("Community waitlist", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/pricing");
  });

  test("(a) valid email submission shows success state", async ({ page }) => {
    const emailInput = page.getByLabel("Email");
    await emailInput.fill(uniqueEmail());
    await emailInput.press("Enter");

    await expect(page.getByRole("status")).toBeVisible({ timeout: 10_000 });
    await expect(page.getByText("You're on the list.")).toBeVisible();
    await expect(page.getByText("We'll email when Community lands.")).toBeVisible();
  });

  test("(b) invalid email shows in-voice error", async ({ page }) => {
    const emailInput = page.getByLabel("Email");
    await emailInput.fill("notanemail");
    await page.getByRole("button", { name: "Sign me up" }).click();

    await expect(page.getByRole("alert")).toBeVisible({ timeout: 10_000 });
    await expect(page.getByText("Couldn't save that.")).toBeVisible();
    await expect(page.getByText("Check the address and try again.")).toBeVisible();
  });

  test("(c) duplicate email submission also shows success (idempotent)", async ({ page }) => {
    const email = uniqueEmail();
    const emailInput = page.getByLabel("Email");

    await emailInput.fill(email);
    await emailInput.press("Enter");
    await expect(page.getByRole("status")).toBeVisible({ timeout: 10_000 });

    await page.goto("/pricing");
    const emailInput2 = page.getByLabel("Email");
    await emailInput2.fill(email);
    await emailInput2.press("Enter");

    await expect(page.getByRole("status")).toBeVisible({ timeout: 10_000 });
    await expect(page.getByText("You're on the list.")).toBeVisible();
  });
});

