import * as Sentry from "@sentry/nextjs";
import { NextRequest, NextResponse } from "next/server";
import { createWaitlistClient, insertWaitlistEntry } from "@/lib/community-waitlist/insert";
import { validateWaitlistPayload } from "@/lib/community-waitlist/validation";
import { runWithContext, scopedLogger } from "@/lib/log";
import { getPostHogClient } from "@/lib/posthog-server";
import { randomUUID } from "crypto";

const log = scopedLogger("community-waitlist");

function json(body: unknown, status: number) {
  return NextResponse.json(body, { status });
}

export async function POST(req: NextRequest) {
  const requestId = randomUUID();

  return runWithContext({ requestId, route: "/community-waitlist" }, async () => {
    log.info("request_received");

    let body: unknown;
    try {
      body = await req.json();
    } catch {
      log.warn("invalid_json");
      return json({ error: "invalid_json" }, 400);
    }

    const validation = validateWaitlistPayload(body);
    if (!validation.ok) {
      log.warn("validation_failed", { kind: validation.error.kind });
      return json({ error: validation.error.kind }, 400);
    }

    const { value: payload } = validation;
    const client = createWaitlistClient();
    const result = await insertWaitlistEntry(client, payload);

    if (result.status === "failed") {
      log.error("insert_failed", { cause: String(result.cause) });
      Sentry.captureException(result.cause, { tags: { route: "/community-waitlist" } });
      return json({ error: "db_error" }, 500);
    }

    if (result.status === "inserted") {
      log.info("waitlist_inserted", { source: payload.source });
      const posthog = getPostHogClient();
      posthog?.capture({
        distinctId: payload.userId ?? `anon-${payload.email}`,
        event: "community_waitlist_signup",
        properties: { source: payload.source, has_user_id: payload.userId !== null },
      });
    } else {
      log.info("waitlist_duplicate", { source: payload.source });
    }

    return json({ ok: true }, 201);
  });
}

