import type { Metadata } from "next";
import Image from "next/image";
import { Container } from "@/components/layout/Container";
import { APP, PRICING } from "@/lib/constants";
import { PricingCard } from "@/components/pricing/PricingCard";
import { PricingSection } from "@/components/pricing/PricingSection";
import { RoadmapCard } from "@/components/marketing/RoadmapCard";
import { CommunityRoadmapCard } from "@/components/community/CommunityRoadmapCard";
import { SignUpButton } from "@/components/ui/SignUpButton";
import { PRICING_ROADMAP } from "@/lib/content/roadmap";

export const metadata: Metadata = {
  title: "Pricing",
  description: `Compare ${APP.name} plans. Free for the basics or ${APP.premiumTier} for unlimited identifications, diagnoses, and saved plants.`,
};

export default function PricingPage() {
  return (
    <main>
      <section className="section-y-sm">
        <Container>
          <div className="flex justify-center">
            <Image
              src="/pricing-hero.png"
              alt="Five cheerful cartoon plants raising their arms in excitement"
              width={800}
              height={560}
              priority
              className="w-full max-w-[320px] sm:max-w-[400px] lg:max-w-[480px]"
            />
          </div>

          <div className="mx-auto max-w-2xl text-center">
            <p className="text-eyebrow font-semibold uppercase text-accent">
              They&rsquo;re rooting for you
            </p>
            <h1 className="mt-5 text-h1 font-medium text-heading">
              Pick a plan. The plants are watching.
            </h1>
            <p className="mt-4 text-lg text-body">
              Start free. Upgrade when you&rsquo;re tired of the silent judgment.
            </p>
          </div>

          <PricingSection>
            <PricingCard name="Free" price="$0" period="forever" features={PRICING.features.free}>
              <SignUpButton variant="secondary" fullWidth />
            </PricingCard>
          </PricingSection>
        </Container>
      </section>

      <section className="section-y-sm">
        <Container>
          <div className="mx-auto max-w-2xl text-center">
            <p className="text-eyebrow font-semibold uppercase text-accent">What&rsquo;s next</p>
            <h2 className="mt-4 text-h2 font-medium text-heading">On the roadmap</h2>
            <p className="mt-3 text-body">
              Not live today. Here so you know where we&rsquo;re headed.
            </p>
          </div>

          <div className="mx-auto mt-10 grid max-w-4xl gap-6 sm:grid-cols-2">
            {PRICING_ROADMAP.map((r) =>
              r.kind === "community" ? (
                <CommunityRoadmapCard key={r.title} icon={r.icon} title={r.title} body={r.body} />
              ) : (
                <RoadmapCard key={r.title} icon={r.icon} title={r.title} body={r.body} />
              ),
            )}
          </div>
        </Container>
      </section>
    </main>
  );
}

