    await waitFor(() => {
      expect(screen.getByRole("status")).toBeInTheDocument();
      expect(screen.getByText(COPY.successHeadline)).toBeInTheDocument();
      expect(screen.getByText(COPY.successBody)).toBeInTheDocument();
